sys_script_include.script:
var AESAnnouncementService = Class.create();
AESAnnouncementService.prototype = {

    initialize: function() {
        this._query = new AESCommunicationQuery();
        this._interactionQuery = new AESCommunicationInteractionQuery();
        this._tracking = new AESCommunicationTracking();
    },
    /**
     * Returns the announcements available for the given context.
     */
    getAvailable: function(options) {
        options = options || {};
        options = this.prepareQueryOptions(options);

        var ids = this._query.getAvailable(options);
        var announcements = this._buildAnnouncements(ids, options);

        return this.afterBuild(
            announcements,
            options
        );
    },

    /**
     * Extension point.
     * Allows implementations to modify query options
     * before AESCommunicationQuery is executed.
     */
    prepareQueryOptions: function(options) {
        return options;
    },


    /**
     * Returns saved announcements available for
     * the given context.
     */
    getSaved: function(options) {
        options = options || {};

        options = this.prepareQueryOptions(options);

        var interactionOptions = this._copyOptions(options);

        interactionOptions.interaction = {
            saved: true
        };

        var ids = this._interactionQuery.getAvailable(interactionOptions);

        var announcements = this._buildAnnouncements(ids, interactionOptions);

        return this.afterBuild(
            announcements,
            interactionOptions
        );
    },

    /**
     * Builds the consumer representation of
     * the available announcements.
     */
    _buildAnnouncements: function(ids, options) {
        var result = [];

        for (var i = 0; i < ids.length; i++) {

            var gr = new GlideRecord('x_733168_aes_announcement');

            if (!gr.get(ids[i]))
                continue;

            var announcement = this._buildAnnouncement(gr, options);

            announcement = this._applyExtensions(announcement, gr, options);

            if (announcement)
                result.push(announcement);
        }

        return result;
    },

    /**
     * Builds the standard AES Announcement DTO.
     */
    _buildAnnouncement: function(gr, options) {
        return {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            title: gr.getDisplayValue('title'),
            short_description: gr.getDisplayValue('short_description'),
            content: gr.getValue('content'),
            priority: {
                value: gr.getValue('priority'),
                label: gr.getDisplayValue('priority')
            },
            publish_date: gr.getValue('publish_date'),
            expiration_date: gr.getValue('expiration_date'),
            image: gr.getValue('image'),
            image_alt_text: gr.getDisplayValue('image_alt_text'),
            glyph: gr.getValue('glyph'),
            glyph_alt_text: gr.getDisplayValue('glyph_alt_text'),
            urgent: gr.getValue('mark_as_urgent') == 'true',
            dismiss_option: gr.getValue('dismiss_option'),
            categories: this._getCategories(gr.getUniqueValue()),
            actions: this._getActions(gr.getUniqueValue()),
            tracking: this._getTracking(gr.getUniqueValue())
        };
    },

    /**
     * Extension point.
     * Allows implementations to enrich or modify
     * a single Announcement DTO.
     */
    _applyExtensions: function(announcement, gr, options) {

        var extensions = new GlideScriptedExtensionPoint().getExtensions('x_733168_aes.AESAnnouncementExtension');

        for (var i = 0; i < extensions.length; i++) {

            try {
                var result = extensions[i].transformAnnouncement(announcement, gr, options);

                if (result)
                    announcement = result;

            } catch (ex) {
                gs.error('[AES] Announcement extension failed: ' + ex.message);
            }
        }

        return announcement;
    },

    _getCategories: function(communicationId) {
        var categories = [];

        var m2m = new GlideRecord('x_733168_aes_communication_m2m_category');

        m2m.addQuery('x_733168_aes_communication', communicationId);
        m2m.query();

        while (m2m.next()) {
            var category = m2m.x_733168_aes_communication_category.getRefRecord();

            if (!category.isValidRecord())
                continue;

            categories.push({
                sys_id: category.getUniqueValue(),
                name: category.getDisplayValue('name'),
                internal_name: category.getValue('internal_name')
            });
        }

        return categories;
    },

    _getActions: function(communicationId) {
        var actions = [];

        var gr = new GlideRecord(
            'x_733168_aes_communication_action'
        );

        gr.addQuery('communication', communicationId);
        gr.orderBy('order');
        gr.query();

        while (gr.next()) {
            actions.push(
                this._buildAction(gr)
            );
        }

        return actions;
    },

    _buildAction: function(gr) {
        var action = {
            sys_id: gr.getUniqueValue(),
            label: gr.getDisplayValue('label'),
            type: gr.getValue('action_type'),
            level: gr.getValue('action_level'),
            target: gr.getValue('link_target'),
            order: parseInt(gr.getValue('order'), 10) || 0
        };

        switch (action.type) {

            case 'url':
                action.url = gr.getValue('url');
                break;

            case 'knowledge_article':
                action.knowledge_article = {
                    sys_id: gr.getValue('knowledge_article'),
                    label: gr.getDisplayValue(
                        'knowledge_article'
                    )
                };
                break;

            case 'catalog_item':
                action.catalog_item = {
                    sys_id: gr.getValue('catalog_item'),
                    label: gr.getDisplayValue(
                        'catalog_item'
                    )
                };
                break;

            case 'agent_chat':
                action.queue = {
                    sys_id: gr.getValue('queue'),
                    label: gr.getDisplayValue('queue')
                };
                break;
        }

        return action;
    },

    _getTracking: function(communicationId) {
        var tracking = this._tracking.getTracking(communicationId);

        if (!tracking)
            return null;

        return {
            displayed: tracking.displayed,
            first_displayed_on: tracking.first_displayed_on,
            last_displayed_on: tracking.last_displayed_on,
            read: tracking.read,
            read_on: tracking.read_on,
            saved: tracking.saved,
            saved_on: tracking.saved_on,
            dismissed: tracking.dismissed,
            dismissed_on: tracking.dismissed_on
        };
    },

    _copyOptions: function(options) {
        var copy = {};

        for (var property in options) {
            if (Object.prototype.hasOwnProperty.call(options, property)) {
                copy[property] = options[property];
            }
        }

        return copy;
    },

    /**
     * Extension point.
     * Allows implementations to modify the final result.
     */
    afterBuild: function(announcements, options) {
        return announcements;
    },

    type: 'AESAnnouncementService'
};
